mapper.select:
-- 영업 사이트 담당자로 선택 가능한 활성 사용자를 쓰기 권한 범위 안에서 조회한다. SELECT u.user_id, u.email, u.name, u.position, COALESCE(( SELECT STRING_AGG(d2.name, ', ' ORDER BY d2.display_order, d2.department_id) FROM user_department_permissions udp2 INNER JOIN departments d2 ON d2.department_id = udp2.department_id WHERE udp2.user_id = u.user_id AND udp2.can_write = TRUE ), '') AS department_permission_summary FROM users u WHERE u.is_active = TRUE AND ( #{allDepartments} = TRUE OR EXISTS ( SELECT 1 FROM user_department_permissions udp INNER JOIN departments d ON d.department_id = udp.department_id WHERE udp.user_id = u.user_id AND udp.can_write = TRUE
AND d.code IN
#{departmentCode}
AND 1 = 0
) ) ORDER BY u.name, u.user_id

-- 선택된 보안 프로젝트 열람자가 활성 사용자 계정인지 검증한다. SELECT u.user_id FROM users u WHERE u.is_active = TRUE AND u.user_id IN
#{userId}
ORDER BY u.user_id

mapper.update:
-- 삭제 대상 사용자가 영업 사이트 작성자, 수정자, 담당자로 참조된 값을 비운다.
UPDATE opportunities
SET
    created_by = CASE WHEN created_by = #{userId} THEN NULL ELSE created_by END,
    updated_by = CASE WHEN updated_by = #{userId} THEN NULL ELSE updated_by END,
    owner_user_id = CASE WHEN owner_user_id = #{userId} THEN NULL ELSE owner_user_id END
WHERE created_by = #{userId}
   OR updated_by = #{userId}
   OR owner_user_id = #{userId}

mapper.delete:
-- 삭제 대상 사용자에게 부여된 보안 프로젝트 열람 권한을 삭제한다.
DELETE FROM opportunity_view_permissions
WHERE user_id = #{userId}

-- 사용자에게 부여된 기존 역할을 삭제한다.
DELETE FROM user_roles
WHERE user_id = #{userId}

-- 사용자에게 부여된 기존 사업본부 권한을 삭제한다.
DELETE FROM user_department_permissions
WHERE user_id = #{userId}

-- 회원/권한 관리에서 사용자를 실제 삭제한다.
DELETE FROM users
WHERE user_id = #{userId}
